'use strict';const {test}=require('node:test'),assert=require('node:assert/strict');const E=require('../src/engine.js'),rows=require('../src/catalog.js');
for(const [s,want] of [['달서구에서 2억 5천 이하, 넓은 집',{district:'달서구',maxDeposit:25000,priority:'space'}],['2억 2,200만 원',{maxDeposit:22200}],['수성구, 2억 이하, 84㎡ 이상',{district:'수성구',maxDeposit:20000,minArea:84}],['보증금 1.5억',{maxDeposit:15000}],['9천만원',{maxDeposit:9000}],['1억 5000',{maxDeposit:15000}],['2억 84㎡',{maxDeposit:20000,minArea:84}],['대구 전체, 저렴한 곳',{district:null,priority:'budget'}],['보증금 제한 없음',{maxDeposit:null}],['서구 아파트',{district:'서구'}]])test('문장 해석: '+s,()=>assert.deepEqual(E.parse(s).patch,want));
for(const s of ['달서구 말고 동구','1억~2억','2억 이상','2억 5천 이상','84㎡ 이하','서울 중구 2억 이하','전세 2억, 학군 좋은 곳','연봉 4000만원','2억과 3억','수성구 또는 북구','30평 2억','월세 50만원','-2억','2억 500원','2억 5천 500만'])test('불확실/미지원 보류: '+s,()=>assert.deepEqual(E.parse(s).patch,{}));
test('답변 단계 기억',()=>{const a={};E.mark({district:null,maxDeposit:20000},a);assert.equal(E.next(a),'priority');assert.deepEqual(E.parse('건너뛰기','priority').patch,{priority:'balance'});});
test('예시 숨김 기본값과 출처',()=>{assert.equal(E.rank(rows,{}).length,1);assert.equal(E.rank(rows,{},true).length,8);assert.ok(rows.every(x=>x.source));});
test('경계 포함 / 순위 / 여유 금액',()=>{const hits=E.rank(rows,{district:'달서구',maxDeposit:22200,minArea:74,priority:'space'},true);assert.deepEqual(hits.map(x=>x.id),['sangin-centerpark','daegok-demo']);assert.ok(hits[0].why.join().includes('상한과 같아요'));assert.ok(hits[1].why.join().includes('1,200만'));});
test('균형 정규화 및 동률 결정',()=>{const top=E.rank(rows,{},true)[0];assert.equal(top.id,'sinam-demo');assert.equal(E.rank([...rows].reverse(),{},true)[0].id,top.id);});
test('정렬 선호를 바꾸어도 필수 조건 보존',()=>{for(const priority of Object.keys(E.modes)){for(const district of [null,...E.districts])for(const cap of [17000,19500,22200,30000]){const h=E.rank(rows,{priority,district,maxDeposit:cap,minArea:74},true);assert.ok(h.every(x=>(!district||x.district===district)&&x.depositMan<=cap&&x.areaM2>=74));}}});
test('후보 없음: 대안은 별도, 승인 전 원본 불변',()=>{const p={...E.base(),district:'수성구',maxDeposit:20000,minArea:84};const before=JSON.stringify(p),alt=E.alternatives(rows,p,true);assert.equal(E.rank(rows,p,true).length,0);assert.ok(alt.some(a=>a.patch.maxDeposit===32000));assert.ok(alt.every(a=>E.rank(rows,{...p,...a.patch},true).length));assert.equal(JSON.stringify(p),before);});
test('샘플만 있는 경우 명시적 포함 가능',()=>assert.ok(E.alternatives(rows,{...E.base(),district:'북구'},false).some(x=>x.samples)));
test('불량 레코드·중복·반전세 제외',()=>assert.equal(E.catalog([rows[0],rows[0],{...rows[1],lease:'반전세'},{...rows[2],source:''},{...rows[3],sample:null},{...rows[4],depositMan:null}]).length,1));
test('AI/호스트 조건 허용키·범위',()=>assert.deepEqual(E.sanitize({maxDeposit:'2억',district:'강남구',minArea:-1,priority:'id',name:'가짜'}),{}));
